let registered = false;

/**
 * Every issue-shaped alert links to the issue's real page, which needs its
 * org and project slugs plus its human-facing number — none of which travel
 * on the event payload. Returns `null` (skip the notification) rather than a
 * dead link when any of the three rows has vanished since the event fired.
 */
async function issueHref(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: typeof issueId extends never ? never : Parameters<typeof issueRepo.findIssueById>[1],
): Promise<string | null> {
  const [org, project, issue] = await Promise.all([
    orgRepo.findOrgById(orgId),
    projectRepo.findProjectById(orgId, projectId),
    issueRepo.findIssueById(orgId, issueId),
  ]);
  if (!org || !project || !issue) return null;
  return issuePath(org.slug, project.slug, issue.number);
}

/** The active owners of an org; billing and membership alerts go to all of them. */
async function listOwnerIds(orgId: OrgId): Promise<readonly UserId[]> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: "active",
    limit: 100,
    cursor: null,
  });
  return page.items.map((member) => member.userId);
