      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await listOwnerIds(payload.orgId);
    if (owners.length === 0) return;

    const label = PLAN_LIMIT_LABELS[payload.resource];
    const title = `Your plan ran out of room for ${label}`;
    const href = settingsPath(org.slug, "billing");

    const recipients: UserId[] = [];
    for (const ownerId of owners) {
      const unread = await notificationRepo.listNotifications({
        orgId: payload.orgId,
        recipientId: ownerId,
        unreadOnly: true,
        kind: ["plan_limit_reached"],
        limit: 100,
        cursor: null,
      });
      const alreadyAlerted = unread.items.some((item) => item.title === title);
      if (!alreadyAlerted) recipients.push(ownerId);
    }

    if (recipients.length === 0) return;

    await notify(payload.orgId, "plan_limit_reached", recipients, {
      title,
      body: `The plan allows ${payload.limit} ${label}; ${payload.used} are in use.`,
      href,
      actorId: null,
    });
  });
}

