/**
 * Every hit links to the page the app actually serves: issues and comments
 * both resolve to their issue's page, projects to their own page. `null`
 * means the row the index points at no longer exists — the hit is dropped
 * rather than linked to a dead page.
 */
async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  row: SearchIndexRow,
): Promise<string | null> {
  switch (row.subjectKind) {
    case "issue":
      return issueHrefFromId(orgId, orgSlug, row.subjectId as Issue["id"]);
    case "comment": {
      const comment = await commentRepo.findCommentById(orgId, row.subjectId);
      if (!comment) return null;
      return issueHrefFromId(orgId, orgSlug, comment.issueId);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        row.subjectId as ProjectId,
      );
      if (!project) return null;
      return projectPath(orgSlug, project.slug);
    }
  }
}

async function issueHrefFromId(
  orgId: OrgId,
  orgSlug: string,
  issueId: Issue["id"],
): Promise<string | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return null;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return null;
  return issuePath(orgSlug, project.slug, issue.number);
}

