 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

/**
 * Every issue-shaped alert links to the issue's real page, which needs its
 * org and project slugs plus its human-facing number — none of which travel
 * on the event payload. Returns `null` (skip the notification) rather than a
 * dead link when any of the three rows has vanished since the event fired.
 */
async function issueHref(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<string | null> {
  const [org, project, issue] = await Promise.all([
    orgRepo.findOrgById(orgId),
    projectRepo.findProjectById(orgId, projectId),
    issueRepo.findIssueById(orgId, issueId),
  ]);
  if (!org || !project || !issue) return null;
  return issuePath(org.slug, project.slug, issue.number);
}

/** The active owners of an org; billing and membership alerts go to all of them. */
async function listOwnerIds(orgId: OrgId): Promise<readonly UserId[]> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: "active",
    limit: 100,
    cursor: null,
  });
  return page.items.map((member) => member.userId);
}

const PLAN_LIMIT_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "seats",
  projects: "projects",
  issuesPerProject: "issues in a project",
  storageMb: "upload storage",
  apiRequestsPerHour: "API requests",
  webhooks: "webhook endpoints",
};

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    if (payload.assigneeId === payload.actorId) return;

    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.title} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.assigned", async (payload) => {
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;
    if (issue.assigneeId === payload.actorId) return;

    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue you're assigned to changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    const href = issue
      ? await issueHref(payload.orgId, issue.projectId, payload.issueId)
      : null;

    if (href !== null) {
      await notify(payload.orgId, "comment_created", watchers, {
        title: "New comment",
        body: `A comment was added to issue ${payload.issueId}`,
        href,
        actorId: payload.actorId,
      });

      if (payload.mentionedUserIds.length > 0) {
        await notify(
          payload.orgId,
          "comment_mention",
          payload.mentionedUserIds,
          {
            title: "You were mentioned",
            body: `You were mentioned on issue ${payload.issueId}`,
            href,
            actorId: payload.actorId,
          },
        );
      }
    }
  });

  // The owner hears about a new member; the person who joined does not get an
  // alert about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await listOwnerIds(payload.orgId);

    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  // One alert per still-unread refusal: while it is unread, further refusals
  // for the same resource add nothing; once it is read, the next refusal
  // starts a new one. The periodic usage recount never sets `refused`, so it
  // never reaches this far.
  subscribe("billing.limit_exceeded", async (payload) => {
    if (!payload.refused) return;

    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await listOwnerIds(payload.orgId);
    if (owners.length === 0) return;

    const label = PLAN_LIMIT_LABELS[payload.resource];
    const title = `Your plan ran out of room for ${label}`;
    const href = settingsPath(org.slug, "billing");

    const recipients: UserId[] = [];
    for (const ownerId of owners) {
      const unread = await notificationRepo.listNotifications({
        orgId: payload.orgId,
        recipientId: ownerId,
        unreadOnly: true,
        kind: ["plan_limit_reached"],
        limit: 100,
        cursor: null,
      });
      const alreadyAlerted = unread.items.some((item) => item.title === title);
      if (!alreadyAlerted) recipients.push(ownerId);
    }

    if (recipients.length === 0) return;

    await notify(payload.orgId, "plan_limit_reached", recipients, {
      title,
      body: `The plan allows ${payload.limit} ${label}; ${payload.used} are in use.`,
      href,
      actorId: null,
    });
  });
}

registerFanOut();
